#!/usr/bin/env bash

# Installs the gdm session entry "Hyprland (nix, uwsm)".
# The file is generated by home-manager (user/hyprland-ubuntu.nix) with an Exec that points to the
# stable profile path. It must be a real file in /usr/share/wayland-sessions (not a link into $HOME,
# the gdm user cannot read /home). It only needs to be installed once; re-run if the file changes.

set -euo pipefail

[[ $(id -u) -gt 0 ]] && {
	echo "please run with sudo"
	exit 1
}

user=${SUDO_USER:?run via sudo from your normal user}
home=$(getent passwd "$user" | cut -d: -f6)
src="$home/.local/state/nix/profile/share/wayland-sessions/hyprland-nix.desktop"

[[ -f $src ]] || {
	echo "$src not found, run home-manager switch first"
	exit 1
}

install -m 644 -o root -g root "$src" /usr/share/wayland-sessions/hyprland-nix.desktop
echo "installed /usr/share/wayland-sessions/hyprland-nix.desktop:"
cat /usr/share/wayland-sessions/hyprland-nix.desktop
